static void require(bool v,const char* text){if(!v)throw std::runtime_error(text);}
static void wait(WubrotProcessor& p){for(int i=0;i<3000&&p.isLoading();++i)juce::Thread::sleep(2);require(!p.isLoading(),"Analysis timeout");}
static std::vector<float> render(WubrotProcessor& p){p.prepareToPlay(48000,128);std::vector<float>out;for(int block=0;block<100;++block){juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;for(int i=0;i<128;++i)b.setSample(0,i,.35f*std::sin((block*128+i)*.031f));b.copyFrom(1,0,b,0,0,128);p.processBlock(b,m);out.insert(out.end(),b.getReadPointer(0),b.getReadPointer(0)+128);}return out;}
static void fresh(WubrotProcessor&p){auto s=p.uiState();require(float(s["mutate"])==100&&float(s["drive"])==0&&float(s["x"])==0&&float(s["y"])==0,"Fresh defaults not applied");require(s["name"].toString().isEmpty()&&s["waveform"].size()==0&&!bool(s["editable"])&&!bool(s["analysisOnly"]),"Fresh instance inherited DNA");require(int(s["xyMapping"])==10&&!p.hasUnsavedPresetChanges(),"Fresh mapping/state dirty");require(double(s["playhead"])==0,"Fresh profile clock running");require(float(s["output"])==0,"Fresh neutral output is not unity");}
