 WubrotProcessor copy(docs);copy.setStateInformation(project.getData(),int(project.getSize()));require(float(copy.uiState()["x"])==float(p.uiState()["x"])&&float(copy.uiState()["mutate"])==42&&float(copy.uiState()["drive"])==7&&!bool(copy.uiState()["enabled"]),"Project/duplicate overwritten by defaults");require(render(copy)==render(p),"Project copy audio differs");
 p.setParameterValue("enabled",1);require(p.saveUserPreset("New mapping").wasOk(),"Modern preset save failed");WubrotProcessor preset(docs);require(preset.loadUserPreset("New mapping.wubpreset").wasOk(),"Modern preset load failed");require(int(preset.uiState()["xyMapping"])==10&&render(preset)==render(p),"Modern preset changed mapping/sound");
