 require(legacy.saveUserPreset("Legacy mapping").wasOk(),"Legacy preset save failed");WubrotProcessor oldPreset(docs);require(oldPreset.loadUserPreset("Legacy mapping.wubpreset").wasOk(),"Legacy preset load failed");require(int(oldPreset.uiState()["xyMapping"])==1&&render(oldPreset)==actual,"Legacy preset recall changed");
